/** Converts a cache entry's numeric risk to the flag string used by INGREDIENT_DB / scorer. */
export function riskToFlag(risk) {
  if (risk >= IngredientRisk.High) return 'avoid';
  if (risk >= IngredientRisk.Medium) return 'moderate';
  return 'ok';
}
